  mhe: { label: 'MHE Fleet Register', hash: '#/import', input: '[data-file]', admin: true },
  billing: { label: 'Billing Activity (customer throughput)', hash: '#/weekly', tab: 'customer', drop: '[data-tp-drop]' },
  elxBilling: { label: 'Electrolit Billing Activity (more than one week — scorecard)', hash: '#/electrolit?tab=drops', drop: '[data-drop="billing"]', page: 'the Electrolit scorecard' },
  wms: { label: 'WMS move export (operator throughput)', hash: '#/weekly', tab: 'operator', drop: '[data-op-drop]' },
  hr: { label: 'HR hours (Detailed Hours Overview or Calculated Time Counters)', hash: '#/weekly', tab: 'labor', drop: '[data-drop]' },
