    if (/^goa[-_ ]|audit|arrival condition|\\bacr\\b|os&d|osd/.test(n)) return /electrolit/.test(n) ? 'ncr' : 'acr';
    // MHE checklists: "MHE Hours WE 11.14.26", "WEEK ENDING 28", "17721   5" (serial + truck #), "forklift checklist".
    if (/\\bmhe\\b|forklift|checklist|inspection|pre-?op|week ?ending|weekend|\\bwe\\s*\\d/.test(n) || /^\\d{4,}\\s+\\d{1,3}\\.pdf$/.test(n)) return 'mheInsp';
    if (/hours|overview|payroll|time|counter/.test(n)) return 'hr';
