const cache = new Map();      // coll -> array of docs ({id, ...data})
const ready = new Map();      // coll -> Promise
const listeners = new Set();
let backend;

export const store = {
  demo,
  user: null,      // { uid, email, name }
  role: null,      // 'pending' | 'viewer' | 'supervisor' | 'manager' | 'admin'
  hidden: [],      // pages an admin has hidden from this user (access.js keys); admins see everything
  savedConfig: { settings: false, rail: false },
  settings: null,  // config/settings doc
  rail: null,      // config/rail doc

  onChange(fn) { listeners.add(fn); return () => listeners.delete(fn); },
  rows(coll) { return cache.get(coll) || []; },

  /** Ensure collections are subscribed; resolves after first data arrives. */
  need(colls) {
    return Promise.all(colls.map(c => {
      if (!ready.has(c)) ready.set(c, backend.subscribe(c, docs => { cache.set(c, docs); emit(c); }, err => readFailed(c, err)));
      return ready.get(c);
    }));
  },
  /** Collections the database refused to read (permission): coll -> error code. Retried on their own. */
  readErrors: new Map(),

  /** Set by app.js (uploads.js ▸ logUploads): told about every add / set / writeMany, to log weekly uploads. */
  afterWrite: null,
  async add(coll, data) {
    const prefix = REF_PREFIX[coll];
    const id = prefix ? await backend.addWithRef(coll, prefix, clean(data)) : await backend.add(coll, clean(data));
    wrote(coll, [data]);
    return id;
  },
  set: (coll, id, data) => backend.set(coll, id, clean(data)).then(r => { wrote(coll, [data]); return r; }),
  /** Read one document once (without subscribing to the whole collection) — e.g. an archived file part. */
  get: (coll, id) => backend.get(coll, id),
  /** Read the documents where field == value, once (no subscription) — e.g. one report's attachments. */
  where: (coll, field, value) => backend.where(coll, field, value),
  update: (coll, id, data) => backend.update(coll, id, clean(data)),
  remove: (coll, id) => backend.remove(coll, id),
  /** Replace a whole collection (used by the Excel importer). docs: [{id?, ...}] */
  replaceAll: (coll, docs, onProgress) => backend.replaceAll(coll, docs, onProgress),
  /** Write many docs: {id?, ...data} upserts (or adds when no id); {_delete: id} deletes. */
  writeMany: (coll, docs) => backend.writeMany(coll, docs).then(r => { wrote(coll, docs); return r; }),
  saveConfig: async (name, data) => { await backend.set('config', name, clean(data)); },

  // auth
  signInGoogle: () => backend.signInProvider('google'),
  signInMicrosoft: () => backend.signInProvider('microsoft'),
  signInEmail: (e, p) => backend.signInEmail(e, p),
  signUpEmail: (e, p) => backend.signUpEmail(e, p),
  resetPassword: e => backend.resetPassword(e),
  sendVerification: () => backend.sendVerification(),
  /** Re-check the signed-in account (e.g. after the user clicked the verification link). */
  refreshUser: () => backend.refreshUser(),
  signOut: () => backend.signOut(),
  listUsers: () => backend.listUsers(),
  setUserRole: (uid, role) => backend.set('users', uid, { role }, true),
  setUserHidden: (uid, hidden) => backend.set('users', uid, { hidden }, true),
  /** Admin: create someone's sign-in (email + password) without signing yourself out. Returns their uid. */
  createAccount: (email, password) => backend.createAccount(email, password),
  /** Admin: write a user's profile / access (e.g. right after createAccount). */
  setUserDoc: (uid, data) => backend.set('users', uid, clean(data), true),
  /** Admin: take away someone's access (their sign-in stops opening the app). */
  removeUser: uid => backend.remove('users', uid),
  /** The signed-in person changes their own password. */
  changePassword: (current, next) => backend.changePassword(current, next),
  /** Demo mode: everything this browser holds, for moving it into the shared database. */
  exportAll: () => backend.exportAll?.() ?? null,

  can(action) {
    const r = this.role;
    const lvl = { pending: 0, viewer: 1, supervisor: 2, manager: 3, admin: 4 }[r] ?? 0;
    return { view: lvl >= 1, edit: lvl >= 2, delete: lvl >= 3, confidential: lvl >= 3, admin: lvl >= 4 }[action];
  },
};

function emit(coll) { for (const fn of listeners) fn(coll); }
/** After a write: the upload log (never blocks or fails the write itself). */
function wrote(coll, docs) {
  if (coll === 'uploadLog' || !store.afterWrite) return;
  Promise.resolve().then(() => store.afterWrite(coll, docs)).catch(e => console.warn('afterWrite', coll, e));
}

// A collection that couldn't be read (e.g. before the database rules allowed it) is subscribed again after a short
// wait, so the page fills in once the rules are fixed, without a reload. Waits 15 s, then longer, up to 5 min.
const retryWait = new Map();
function readFailed(coll, err) {
  store.readErrors.set(coll, err?.code || err?.message || 'error');
  emit('readError');
  const wait = Math.min((retryWait.get(coll) || 7500) * 2, 300000);
  retryWait.set(coll, wait);
  setTimeout(() => {
    ready.delete(coll);
    store.readErrors.delete(coll);
    store.need([coll]).then(() => { if (!store.readErrors.has(coll)) { retryWait.delete(coll); emit('readError'); } });
  }, wait);
}
function clean(o) {
  const out = {};
  for (const [k, v] of Object.entries(o)) if (k !== 'id' && v !== undefined) out[k] = v;
  return out;
}

/** Boot: resolves the auth state via callback(user|null). Loads config docs once signed in. */
export async function boot(onAuth) {
  backend = demo ? demoBackend() : await firebaseBackend();
  backend.onAuth(async user => {
    store.user = user;
    const acc = user ? await backend.ensureUserDoc(user) : { role: null, hidden: [] };
    store.role = acc.role; store.hidden = acc.hidden || [];
    if (user && store.can('view')) await loadConfig();
    onAuth(user);
    // An admin changing this user's role or hidden pages takes effect right away.
    // An admin removing this user (their profile deleted) closes the app for them.
    if (user && !demo) backend.watchDoc('users', user.uid, d => {
      const hidden = d.hidden || [], role = d.role || (isAdminEmail(user.email) ? store.role : 'none');
      if (role !== store.role || JSON.stringify(hidden) !== JSON.stringify(store.hidden)) { store.role = role; store.hidden = hidden; emit('access'); }
    });
  });
}

/** Josh Piper and Omar Contreras (config.js ▸ adminEmails) are always admins. */
export const isAdminEmail = email => adminEmails.map(e => e.toLowerCase()).includes(String(email || '').toLowerCase());

async function loadConfig() {
  let gotS = false, gotR = false;
  await new Promise(res => {
    const check = () => { if (gotS && gotR) res(); };
    // savedConfig: whether each config doc has ever been saved (the Excel import fills only empty settings fully).
    backend.watchDoc('config', 'settings', d => { store.settings = withDefaults(d); store.savedConfig.settings = Object.keys(d || {}).length > 0; if (!gotS) { gotS = true; check(); } emit('config'); });
    backend.watchDoc('config', 'rail', d => { store.rail = withRailDefaults(d); store.savedConfig.rail = Object.keys(d || {}).length > 0; if (!gotR) { gotR = true; check(); } emit('config'); });
  });
}

