ATL_SRC.push(['@atl/views/docs.js', 0, `// SOP / Documents: the document library — folder tree, full-text search, and a reader for each document.
// Content comes from forms/library.js (built from the SOP and SQF folders). "Open original" opens the source file on
// this PC (OneDrive); Word / PowerPoint documents can also be read right here.
import { store } from '@atl/store.js';
import { esc, toast, downloadBlob } from '@atl/util.js';
import { LIBRARY, LIB_ROOTS } from '@atl/forms/library.js';
import { libraryEntries } from '@atl/mheinsp.js';
import { docBlob, openDoc, saveDocBlob, fmtSize } from '@atl/mhedocs.js';

const TYPE = { docx: 'Word', doc: 'Word', pptx: 'PowerPoint', pdf: 'PDF', xlsx: 'Excel' };
const ICON = { docx: '📄', doc: '📄', pptx: '📊', pdf: '📕', xlsx: '📗' };
/** Documents this user may see (answer keys and manager templates are for managers). */
// Plus the MHE inspection checklists saved from the weekly drop (MHE Inspections ▸ building ▸ year ▸ month).
const visible = () => [...LIBRARY.map((d, i) => ({ ...d, i })).filter(d => !d.mgr || store.can('confidential')), ...libraryEntries()];
const plain = d => (d.blocks || []).map(b => (b[0] === 'h' ? b[2] : b[0] === 'tr' ? b[1].join(' ') : b[1])).join('\\n');
let textCache;
const textOf = d => ((textCache ||= new Map()).get(d.i) ?? (textCache.set(d.i, plain(d).toLowerCase()), textCache.get(d.i)));
const fileUrl = d => 'file:///' + \`\${LIB_ROOTS[d.root]}\\\\\${d.file}\`.replace(/\\\\/g, '/').split('/').map(encodeURIComponent).join('/').replace(/^([A-Za-z])%3A/, '$1:');
const link = (q) => '#/docs' + (Object.keys(q).length ? '?' + new URLSearchParams(q) : '');

/** Folder tree: { name, path, docs[], kids: Map } built from "Top/Sub/Sub" folder paths. */
function tree(docs) {
  const root = { name: '', path: '', docs: [], kids: new Map() };
  for (const d of docs) {
    let node = root;
    for (const part of d.folder.split('/')) {
      const path = node.path ? \`\${node.path}/\${part}\` : part;
      if (!node.kids.has(part)) node.kids.set(part, { name: part, path, docs: [], kids: new Map() });
      node = node.kids.get(part);
    }
    node.docs.push(d);
  }
  return root;
}
const countIn = n => n.docs.length + [...n.kids.values()].reduce((a, k) => a + countIn(k), 0);

function treeHtml(node, open, cur) {
  return [...node.kids.values()].map(k => {
    const isOpen = open && (open === k.path || open.startsWith(k.path + '/')) || cur?.folder === k.path || cur?.folder.startsWith(k.path + '/');
    return \`<details class="lib-folder"\${isOpen ? ' open' : ''}><summary><a href="\${link({ f: k.path })}" class="lib-fname\${open === k.path ? ' on' : ''}">📁 \${esc(k.name)}</a><span class="lib-count">\${countIn(k)}</span></summary>
      <div class="lib-kids">\${treeHtml(k, open, cur)}\${k.docs.map(d => \`<a class="lib-doc\${cur?.i === d.i ? ' on' : ''}" href="\${link({ d: d.i })}" title="\${esc(d.title)}"\${cur?.i === d.i ? ' aria-current="page"' : ''}><span aria-hidden="true">\${ICON[d.type] || '📄'}</span> \${esc(d.title)}</a>\`).join('')}</div></details>\`;
  }).join('');
}

/**
 * Word download of a library document (Nov 2026, from Josh): its headings, paragraphs, bullet lists and tables, rebuilt
 * as a .docx (same Word builder as the monthly reports). The first row of each table is its header row.
 */
async function wordExport(d) {
  const { reportDocx } = await import('@atl/forms/elxreport.js');
  const out = [{ t: 'h1', text: d.title }];
  if (d.number || d.folder) out.push({ t: 'note', text: [d.number, d.folder.replace(/\\//g, ' › ')].filter(Boolean).join(' · ') });
  let list = [], rows = [];
  const flush = () => {
    if (list.length) { out.push({ t: 'bullets', items: list }); list = []; }
    if (rows.length) {
      const n = Math.max(...rows.map(r => r.length)), pad = r => [...r.map(c => String(c ?? '')), ...Array(n - r.length).fill('')];
      const w = Math.floor(10080 / n);
      out.push({ t: 'table', widths: Array(n).fill(w), head: pad(rows[0]), rows: rows.slice(1).map(pad) });
      rows = [];
    }
  };
  for (const b of d.blocks || []) {
    if (b[0] === 'li') { if (rows.length) flush(); list.push(b[1]); continue; }
    if (b[0] === 'tr') { if (list.length) flush(); rows.push(b[1]); continue; }
    flush();
    if (b[0] === 'h') out.push({ t: b[1] <= 1 ? 'h1' : 'h2', text: b[2] });
    else out.push({ t: 'p', text: b[1] });
  }
  flush();
  const name = \`\${d.number ? d.number + ' ' : ''}\${d.title}\`.replace(/[\\\\/:*?"<>|]+/g, '-').trim().slice(0, 120);
  downloadBlob(\`\${name}.docx\`, reportDocx(out, \`\${d.number ? d.number + ' · ' : ''}\${d.title} · Piper Warehouse\`));
}

/** Render a document's blocks: headings, paragraphs, bullet lists, tables. Search words are highlighted. */
function reader(d, words) {
  const mark = s => { let h = esc(s); for (const w of words) h = h.replace(new RegExp(\`(\${w.replace(/[.*+?^\${}()|[\\]\\\\]/g, '\\\\$&')})\`, 'gi'), '<mark>$1</mark>'); return h; };
  const out = []; let list = [], rows = [];
  const flush = () => {
    if (list.length) { out.push(\`<ul>\${list.map(t => \`<li>\${mark(t)}</li>\`).join('')}</ul>\`); list = []; }
    if (rows.length) { out.push(\`<div class="lib-tbl"><table>\${rows.map(r => \`<tr>\${r.map(c => \`<td>\${mark(c)}</td>\`).join('')}</tr>\`).join('')}</table></div>\`); rows = []; }
  };
  for (const b of d.blocks || []) {
    if (b[0] === 'li') { if (rows.length) flush(); list.push(b[1]); continue; }
    if (b[0] === 'tr') { if (list.length) flush(); rows.push(b[1]); continue; }
    flush();
    out.push(b[0] === 'h' ? \`<h\${Math.min(5, b[1] + 2)}>\${mark(b[2])}</h\${Math.min(5, b[1] + 2)}>\` : \`<p>\${mark(b[1])}</p>\`);
  }
  flush();
  return out.join('');
}

export default {
  needs: () => ['mheDocs'],
  render(p) {
    const docs = visible(), q = (p.query.q || '').trim(), words = q.toLowerCase().split(/\\s+/).filter(w => w.length > 1);
    const cur = p.query.d != null ? docs.find(d => String(d.i) === String(p.query.d)) : null, open = p.query.f || '';
    const root = tree(docs);
    let main;
    if (cur) {
      const crumbs = cur.folder.split('/').map((part, i, a) => \`<a href="\${link({ f: a.slice(0, i + 1).join('/') })}">\${esc(part)}</a>\`).join(' › ');
      main = \`<article class="lib-read">
        <div class="lib-crumbs">\${crumbs}</div>
        <h1>\${ICON[cur.type] || '📄'} \${esc(cur.title)}</h1>
        <div class="lib-meta">\${cur.number ? \`<span class="badge info">\${esc(cur.number)}</span>\` : ''}<span class="badge">\${TYPE[cur.type] || cur.type}</span>\${cur.mgr ? '<span class="badge warn">Managers only</span>' : ''}
          <span class="sp"></span>\${cur.up ? \`<span class="muted small">\${esc(fmtSize(cur.up.size || 0))}\${cur.up.addedBy ? ' · added by ' + esc(cur.up.addedBy) : ''}</span><button type="button" class="btn ghost small" data-up-open>Open PDF ↗</button><button type="button" class="btn ghost small" data-up-save>⬇ Download</button>\` : ''}\${cur.blocks ? \`<button type="button" class="btn ghost small" data-lib-word="\${cur.i}" title="Download this document as a Word file">⬇ Word (.docx)</button>\` : ''}\${cur.up ? '' : \`<a class="btn ghost small" href="\${fileUrl(cur)}" target="_blank" rel="noopener" title="\${esc(cur.file)}">Open original ↗</a>\`}</div>
        \${cur.blocks ? \`<div class="lib-body">\${reader(cur, words)}</div>\`
          : cur.up ? \`<div class="lib-pdf"><iframe data-up-view title="\${esc(cur.title)}"></iframe><p class="muted small" data-up-msg>Loading…</p></div>\`
          : \`<div class="lib-nofile"><p>This is a \${TYPE[cur.type] || cur.type} file — open the original to view it.</p></div>\`}
        <p class="muted small lib-note">\${cur.up ? \`Saved from the weekly MHE inspection drop\${cur.up.notes ? ' (' + esc(cur.up.notes) + ')' : ''}. Also on the truck’s Documents in MHE Fleet.\` : '“Open original” opens the file from OneDrive on this PC. The text shown here is a copy taken when the library was built; the original is the controlled version. ⬇ Word downloads this text as a Word document.'}</p></article>\`;
    } else if (words.length) {
      const hits = docs.map(d => {
        const text = textOf(d), title = d.title.toLowerCase();
        if (!words.every(w => text.includes(w) || title.includes(w) || d.folder.toLowerCase().includes(w) || d.number.toLowerCase().includes(w))) return null;
        const score = words.reduce((a, w) => a + (title.includes(w) ? 50 : 0) + (text.split(w).length - 1), 0);
        const at = Math.max(0, text.indexOf(words[0]) - 70), snip = text ? plain(d).slice(at, at + 200) : '';
        return { d, score, snip };
      }).filter(Boolean).sort((a, b) => b.score - a.score);
      main = \`<div class="lib-results"><h2>\${hits.length} document\${hits.length === 1 ? '' : 's'} match “\${esc(q)}”</h2>\${hits.slice(0, 60).map(h => \`<a class="lib-hit" href="\${link({ d: h.d.i, q })}">
        <b>\${ICON[h.d.type] || '📄'} \${esc(h.d.title)}</b><span class="muted small">\${esc(h.d.folder)}\${h.d.number ? ' · ' + esc(h.d.number) : ''}</span>
        \${h.snip ? \`<span class="lib-snip">…\${reader({ blocks: [['p', h.snip]] }, words).replace(/^<p>|<\\/p>$/g, '')}…</span>\` : ''}</a>\`).join('') || '<p class="muted">Nothing found — try fewer or different words.</p>'}</div>\`;
    } else {
      const node = open ? open.split('/').reduce((n, part) => n?.kids.get(part), root) : null;
      const kids = [...(node || root).kids.values()];
      main = \`<div class="lib-home">\${node ? \`<div class="lib-crumbs">\${open.split('/').map((part, i, a) => \`<a href="\${link({ f: a.slice(0, i + 1).join('/') })}">\${esc(part)}</a>\`).join(' › ')}</div><h2>📁 \${esc(node.name)}</h2>\` : '<h2>Folders</h2>'}
        \${kids.length ? \`<div class="lib-cards">\${kids.map(k => \`<a class="lib-card" href="\${link({ f: k.path })}"><span class="lib-card-ic" aria-hidden="true">📁</span><b>\${esc(k.name)}</b><span class="muted small">\${countIn(k)} document\${countIn(k) === 1 ? '' : 's'}</span></a>\`).join('')}</div>\` : ''}
        \${node?.docs.length ? \`<ul class="lib-list">\${node.docs.map(d => \`<li><a href="\${link({ d: d.i })}"><span aria-hidden="true">\${ICON[d.type] || '📄'}</span> \${esc(d.title)}</a>\${d.number ? \` <span class="badge">\${esc(d.number)}</span>\` : ''} <span class="muted small">\${TYPE[d.type] || d.type}</span></li>\`).join('')}</ul>\` : ''}</div>\`;
    }
    return \`<div class="log-xl lib-xl">
      <div class="xl-dash-head log-head"><div class="xl-banner"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;SOP / Documents</h1>
        <p>Every SOP, policy, work instruction, form and SQF program document in one place. Search all of them, read Word and PowerPoint documents here, or open the original.</p></div>
        <div class="xl-meta"><b>Documents:</b><span class="xl-year">\${docs.length}</span><b>Folders</b><span class="xl-thru">\${root.kids.size}</span>
          <form class="lib-search" data-lib-search role="search"><input type="search" name="q" value="\${esc(q)}" placeholder="Search all documents (e.g. allergen, hairnet, dock plate)…" aria-label="Search all documents"><button class="btn primary small">Search</button></form></div></div>
      <div class="lib-grid"><nav class="lib-tree card" aria-label="Document folders"><a class="lib-all\${!cur && !open && !words.length ? ' on' : ''}" href="#/docs">🏠 All folders</a>\${treeHtml(root, open, cur)}</nav>
        <section class="lib-main card">\${main}</section></div></div>\`;
  },
  after(root, p) {
    root.querySelector('[data-lib-search]')?.addEventListener('submit', e => {
      e.preventDefault(); const q = e.target.q.value.trim();
      location.hash = link(q ? { q } : {});
    });
    // A saved MHE checklist: show it here, open it in a tab, or download it.
    const up = p?.query?.d && String(p.query.d).startsWith('u-') ? visible().find(x => String(x.i) === String(p.query.d))?.up : null;
    if (up) {
      root.querySelector('[data-up-open]')?.addEventListener('click', () => openDoc(up).catch(e => toast(e.message, 'bad')));
      root.querySelector('[data-up-save]')?.addEventListener('click', () => saveDocBlob(up).catch(e => toast(e.message, 'bad')));
      const fr = root.querySelector('[data-up-view]'), msg = root.querySelector('[data-up-msg]');
      docBlob(up).then(b => { fr.src = URL.createObjectURL(b); msg.remove(); }).catch(e => { msg.textContent = 'Could not load the file: ' + e.message; });
    }
    root.querySelector('[data-lib-word]')?.addEventListener('click', async e => {
      const btn = e.currentTarget, d = visible().find(x => x.i === +btn.dataset.libWord);
      if (!d) return;
      btn.disabled = true;
      try { await wordExport(d); toast('Word document downloaded'); }
      catch (err) { console.error(err); toast('Could not build the Word file: ' + err.message, 'bad'); }
      btn.disabled = false;
    });
    // Keep the open document in view in the folder tree.
    root.querySelector('.lib-doc.on')?.scrollIntoView({ block: 'nearest' });
  },
};`]);

