ATL_SRC.push(['@atl/views/inmodeview.js', 0, `// Inbound — rail vs truck: ONE view shared by Customer History (one customer) and the dashboards' Throughput tab
// (the whole building), so both look identical. Tiles, a two-line chart (rail cars, truck loads by month), the
// month-by-month table and the rail car list. 6049 shows counts only; 6021 also shows tons.
import { esc, fmtNum, fmtPct, weekEnding, isISO, norm } from '@atl/util.js';
import { kpi, chart, chartBox } from '@atl/ui.js';
import { railTrips } from '@atl/inmode.js';
import { store } from '@atl/store.js';
import { derive } from '@atl/calc.js';
import { isCustomer } from '@atl/throughput.js';

// ---------------------------------------------------------------- rail cars from the Rail & Demurrage tracker
// Rail cars received are counted from the rail tracker (Josh, Nov 2026 — it matches the 2025 totals: Smurfit Westrock
// 303, Catalyst 102, International Paper 87): one car per tracker entry, received on its CP date (or placed / ordered
// when there's no CP). The Billing Activity still gives the truck loads and the tons / pallets by rail vs truck.
const clean = s => norm(s).replace(/[^A-Z]/g, '');
/** Does a rail tracker customer name ("WestRock") mean this throughput customer ("Smurfit Westrock" in 6021)? */
export function railNameIs(railName, customer, building) {
  const set = (store.settings?.throughputCustomers || []).find(c => c.name === customer && (!building || String(c.building) === String(building)));
  if (set && isCustomer(set, railName)) return true;
  const a = clean(railName), b = clean(customer);
  return !!a && !!b && (a === b || (a.length >= 4 && b.includes(a)) || (b.length >= 4 && a.includes(b)));
}
// Received = the car's received date, exactly as Rail & Demurrage counts "cars received": the CP date, or the placed
// date when the car never got a CP (calc.js ▸ railcars ▸ received).
const received = r => (isISO(r.received) ? r.received : '');
/** Tracker cars for one customer → [{ car, date }]. */
export const trackerCarsFor = (customer, building) => derive('railcars').filter(r => r.car && railNameIs(r.customer, customer, building)).map(r => ({ car: r.car, date: received(r) })).filter(x => x.date);
/** Is a rail customer in this building? (its building in Settings ▸ Rail, else matched to a throughput customer there) */
export function railCustomerIn(name, building) {
  const rc = store.rail?.customers || [], c = rc.find(x => x.name === name);
  if (c?.building) return String(c.building) === String(building);
  return (store.settings?.throughputCustomers || []).filter(t => String(t.building) === String(building)).some(t => railNameIs(name, t.name, building));
}
/** Tracker cars for a building (rail customers set up for it in Settings ▸ Rail, else by their throughput customer). */
export function trackerCarsForBuilding(building) {
  const inB = name => railCustomerIn(name, building);
  return derive('railcars').filter(r => r.car && inB(r.customer)).map(r => ({ car: r.car, date: received(r) })).filter(x => x.date);
}

const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const ymLabel = ym => \`\${MON[+ym.slice(5, 7) - 1]} \${ym.slice(0, 4)}\`;
const us = iso => (iso ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(2, 4)}\` : '');
const th = cols => \`<thead><tr>\${cols.map(c => \`<th>\${c}</th>\`).join('')}</tr></thead>\`;
const n0 = v => (typeof v === 'number' ? v : 0);
const ratio = (a, b) => (b > 0 ? a / b : '');
const hasMode = r => typeof r.railIn === 'number' || typeof r.truckIn === 'number';

/**
 * opts: { building, rows (throughput rows: the customer's or the building's), from, to (week endings, inclusive),
 *   unit ('pallets' | 'tons' | 'MT'), factor (tons → shown unit), dec (decimals), chartId, emptyHtml }
 * → { html, draw() } — html is the section body; draw() draws the chart once the html is on the page.
 */
export function modeView(o) {
  const inR = we => we >= o.from && we <= o.to;
  const rows = o.rows.filter(r => inR(r.weekEnding) && hasMode(r));
  // Rail cars: the Rail & Demurrage tracker when it has cars in the range (o.tracker), else the cars found on the
  // Billing Activity lines. A car counts in the range when its week (the Saturday ending its week) is in it.
  // Tracker cars count by their CP date's calendar month and range (dateFrom / dateTo), like Rail & Demurrage — not by week.
  const dFrom = o.dateFrom || o.from, dTo = o.dateTo || o.to;
  const fromTracker = (o.tracker || []).filter(t => t.date >= dFrom && t.date <= dTo).map(t => ({ car: t.car, date: t.date, last: t.date, we: t.date })).sort((a, b) => a.date.localeCompare(b.date));
  const useTracker = fromTracker.length > 0;
  if (!rows.length && !useTracker) return { html: o.emptyHtml || '', draw: () => {} };
  const f = o.factor || 1, u = o.unit, F = v => fmtNum(v, o.dec ?? 0);
  const trips = useTracker ? fromTracker : railTrips(o.rows.flatMap(r => r.railCarsIn || [])).map(t => ({ ...t, we: weekEnding(t.date) })).filter(t => inR(t.we));
  const months = new Map(), month = ym => months.get(ym) || months.set(ym, { ym, rail: 0, truck: 0, cars: 0, truckLoads: 0 }).get(ym);
  for (const r of rows) { const x = month(r.weekEnding.slice(0, 7)); x.rail += n0(r.railIn) * f; x.truck += n0(r.truckIn) * f; x.truckLoads += n0(r.truckLoadsIn); }
  for (const t of trips) month(t.we.slice(0, 7)).cars++;
  const ms = [...months.values()].sort((a, b) => a.ym.localeCompare(b.ym));
  const sum = k => ms.reduce((a, x) => a + x[k], 0);
  const R = sum('rail'), Tr = sum('truck'), cars = sum('cars'), tl = sum('truckLoads'), arr = cars + tl;
  // 6049 (Electrolit and the other pallet customers): counts only — rail cars vs truck loads (Josh, Nov 2026).
  const counts = String(o.building) === '6049';
  const tiles = counts ? [
    kpi('Rail cars in', fmtNum(cars), 'by rail'),
    kpi('Truck loads in', fmtNum(tl), 'one per BL #'),
    kpi('Inbound arrivals', fmtNum(arr), 'rail cars + truck loads'),
    kpi('Arrivals by rail', fmtPct(ratio(cars, arr), 1), arr ? \`\${fmtPct(ratio(tl, arr), 1)} by truck\` : ''),
  ] : [
    kpi('Rail cars in', fmtNum(cars), \`\${F(R)} \${u} by rail\`),
    kpi('Truck loads in', fmtNum(tl), \`\${F(Tr)} \${u} by truck\`),
    kpi('Inbound by rail', fmtPct(ratio(R, R + Tr), 1), \`of \${F(R + Tr)} \${u} received\`),
    kpi(\`\${u[0].toUpperCase() + u.slice(1)} per rail car\`, cars ? fmtNum(R / cars, 1) : '—', tl ? \`\${fmtNum(Tr / tl, 1)} per truck load\` : ''),
  ];
  const tr = ms.slice().reverse().map(x => counts
    ? \`<tr><td class="lbl">\${ymLabel(x.ym)}</td><td>\${fmtNum(x.cars)}</td><td>\${fmtNum(x.truckLoads)}</td><td>\${fmtNum(x.cars + x.truckLoads)}</td><td>\${fmtPct(ratio(x.cars, x.cars + x.truckLoads), 0)}</td><td>\${F(x.rail)}</td><td>\${F(x.truck)}</td></tr>\`
    : \`<tr><td class="lbl">\${ymLabel(x.ym)}</td><td>\${fmtNum(x.cars)}</td><td>\${F(x.rail)}</td><td>\${fmtNum(x.truckLoads)}</td><td>\${F(x.truck)}</td><td>\${fmtPct(ratio(x.rail, x.rail + x.truck), 0)}</td></tr>\`).join('');
  const html = \`<div class="xl-tiles q ch-tiles">\${tiles.join('')}</div>
    <div class="ch-grid"><div class="xl-chart"><h4>Inbound arrivals by month — rail cars and truck loads</h4>\${chartBox(o.chartId, 260, 'Rail cars and truck loads in per month')}</div>
    <div class="xl-chart"><h4>Inbound \${u} by month — rail vs truck</h4>\${chartBox(o.chartId + '-amt', 260, \`Inbound \${u} by rail and by truck per month\`)}</div></div>
    <div class="xl-otif-wrap" style="margin-top:14px"><table class="xl-otif">\${th(counts ? ['Month', 'Rail cars', 'Truck loads', 'Arrivals', '% by rail', \`\${u} by rail\`, \`\${u} by truck\`] : ['Month', 'Rail cars', \`\${u} by rail\`, 'Truck loads', \`\${u} by truck\`, '% by rail'])}<tbody>\${tr}</tbody></table></div>
    \${trips.length ? \`<details class="elx-more"><summary>Rail cars (\${trips.length})\${useTracker ? ' — from the Rail &amp; Demurrage tracker' : ''}</summary><div class="xl-otif-wrap"><table class="xl-otif">\${th(useTracker ? ['Rail car', 'Received (CP)'] : ['Rail car', 'First line', 'Last line'])}<tbody>\${trips.slice().reverse().map(t => useTracker ? \`<tr><td class="lbl">\${esc(t.car)}</td><td>\${us(t.date)}</td></tr>\` : \`<tr><td class="lbl">\${esc(t.car)}</td><td>\${us(t.date)}</td><td>\${t.last !== t.date ? us(t.last) : ''}</td></tr>\`).join('')}</tbody></table></div></details>\` : ''}
    <p class="xl-foot">\${useTracker ? 'Rail cars: from the Rail &amp; Demurrage tracker — one per car received, in the month of its CP date — or its placed date when it never got a CP (same count as Rail &amp; Demurrage). ' : 'Rail cars: from the Billing Activity lines — all lines for the same car within 7 days are one car (the Rail tracker has no cars for this range). '}Truck loads and \${u} by rail vs truck: from the inbound lines of the Billing Activity files — Carrier CSX, a railcar named in the PO or Note, or a BL of 46,000 lbs or more = rail; anything else = truck (one load per BL #). Weeks posted before this was added have no split — drop their files again on Weekly Entry or in the Customer History history box to add it.</p>\`;
  // Two lines (rail cars, truck loads) and the bars (pallets / tons by rail vs truck).
  const draw = () => { drawLines(); chart(o.chartId + '-amt', { type: 'bar', data: { labels: ms.map(x => ymLabel(x.ym)), datasets: [
    { label: \`By rail (\${u})\`, data: ms.map(x => +x.rail.toFixed(1)), backgroundColor: '#222b36', stack: 's', borderRadius: 2 },
    { label: \`By truck (\${u})\`, data: ms.map(x => +x.truck.toFixed(1)), backgroundColor: '#c0904d', stack: 's', borderRadius: 2 },
  ] }, options: { interaction: { mode: 'index', intersect: false }, plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, padding: 12 } } },
    scales: { x: { stacked: true, grid: { display: false } }, y: { stacked: true, beginAtZero: true, title: { display: true, text: u }, ticks: { callback: v => v.toLocaleString() } } } } }); };
  const drawLines = () => chart(o.chartId, { type: 'line', data: { labels: ms.map(x => ymLabel(x.ym)), datasets: [
    { label: 'Rail cars', data: ms.map(x => x.cars), borderColor: '#222b36', backgroundColor: '#222b36', pointBackgroundColor: '#fff', pointRadius: 4, pointBorderWidth: 2, borderWidth: 3, tension: 0.2 },
    { label: 'Truck loads', data: ms.map(x => x.truckLoads), borderColor: '#c0904d', backgroundColor: '#c0904d', pointBackgroundColor: '#fff', pointRadius: 4, pointBorderWidth: 2, borderWidth: 3, tension: 0.2 },
  ] }, options: { interaction: { mode: 'index', intersect: false }, plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, padding: 12 } } },
    scales: { x: { grid: { display: false } }, y: { beginAtZero: true, ticks: { precision: 0 }, title: { display: true, text: 'Arrivals' } } } } });
  return { html, draw };
}`]);

