ATL_SRC.push(['@atl/views/records.js', 0, `// Records: every log in one place, grouped and searchable (the sidebar keeps only the most-used ones).
import { store } from '@atl/store.js';
import { esc, $, $$ } from '@atl/util.js';
import { isHidden } from '@atl/access.js';

/** [href, name, what it holds, group]. Same addresses as before, so bookmarks keep working. */
export const RECORDS = () => [
  ['#/log/otif', 'OTIF Log', 'Order accuracy and quality incidents, one row per incident', 'Quality & safety'],
  ['#/safety', 'Safety Incidents', 'Incident / near miss reports, OSHA 300 Log and 300A Summary', 'Quality & safety'],
  ['#/log/damage', 'Damage Log', 'Product damage, cause, estimated $ and claim status', 'Quality & safety'],
  ['#/log/elxNcr', 'Electrolit NCRs', 'Non-conformance reports for Electrolit', 'Customers'],
  ['#/log/wrAcr', 'WestRock ACRs', 'Smurfit WestRock corrective action requests', 'Customers'],
  ['#/log/trucks', 'Truck Appointments', 'Inbound and outbound truck appointments', 'Customers'],
  ['#/log/throughput', 'Customer Throughput', 'Weekly volume in and out per customer', 'Customers'],
  ['#/log/attendance', 'Attendance Log', 'Tardies, absences and early departures', 'People'],
  ['#/log/recognition', 'Recognition', 'Monthly awards', 'People'],
  ...(store.can('confidential') ? [['#/log/discipline', 'Disciplinary Log', 'Write-ups and active periods (managers and HR only)', 'People']] : []),
  ['#/log/employees', 'Employees', 'The roster: buildings, IDs, WMS usernames, status', 'People'],
  ['#/log/labor', 'Labor', 'Weekly hours per person from the HR export', 'Labor & productivity'],
  ['#/log/opmoves', 'Operator Moves', 'Put aways and picks per operator per day (WMS export)', 'Labor & productivity'],
].filter(r => !isHidden(r[0]));

let q = '';
export default {
  needs: () => [],
  render() {
    const list = RECORDS(), groups = [...new Set(list.map(r => r[3]))];
    const card = ([h, n, d]) => \`<a class="rec-card" href="\${h}" data-rec="\${esc((n + ' ' + d).toLowerCase())}"><b>\${esc(n)}</b><span>\${esc(d)}</span></a>\`;
    return \`<div class="page-head"><div><p class="sub">Every log in the app. The most-used ones are also in the menu.</p></div></div>
      <div class="rec-search"><input type="search" data-rec-q placeholder="Find a log…" aria-label="Find a log" value="\${esc(q)}"></div>
      \${groups.map(g => \`<section class="rec-group"><h2>\${esc(g)}</h2><div class="rec-grid">\${list.filter(r => r[3] === g).map(card).join('')}</div></section>\`).join('')}
      <p class="muted small rec-none" hidden>No log matches that search.</p>\`;
  },
  after(root) {
    const inp = $('[data-rec-q]', root);
    const apply = () => {
      const t = q.trim().toLowerCase();
      let any = false;
      $$('.rec-card', root).forEach(c => { const on = !t || c.dataset.rec.includes(t); c.hidden = !on; any ||= on; });
      $$('.rec-group', root).forEach(s => { s.hidden = !s.querySelector('.rec-card:not([hidden])'); });
      $('.rec-none', root).hidden = any;
    };
    inp?.addEventListener('input', () => { q = inp.value; apply(); });
    apply();
  },
};`]);

