ATL_SRC.push(['@atl/views/uploadsui.js', 0, `// Weekly uploads: the Command Center card, the banner + bell at the top of the app, and the Outlook reminder.
// The rules (what counts as uploaded / late / missing) are in ../uploads.js.
import { store } from '@atl/store.js';
import { esc, addDays, toast } from '@atl/util.js';
import { openEmail } from '@atl/forms/email.js';
import { BLDGS, FEEDS, weekUploads, cardWeek, overdueUploads, itemText, seesAlerts, confirmNone, reminderEmail, missingEmails, shortDate as md, CHECK_FROM, alertAt } from '@atl/uploads.js';

const TONE = { ok: 'good', late: 'warn', partial: 'bad', missing: 'bad', due: 'neutral' };
const pill = (tone, text) => \`<span class="pill \${tone}">\${esc(text)}</span>\`;

/** The Weekly uploads card for the Command Center (last full week, plus the 8 weeks before on request). */
export function uploadsCard() {
  const we = cardWeek(), rows = weekUploads(we), due = overdueUploads(), now = new Date();
  const mine = rows.flatMap(r => BLDGS.map(b => r.cells[b])), late = mine.filter(s => s.overdue).length;
  const before = now < alertAt(we), earlier = due.filter(s => s.we !== we).length;
  const head = late ? pill('bad', \`\${late} late\`) : before && mine.some(s => s.state === 'due') ? pill('neutral', \`Due Mon \${md(addDays(we, 2))}\`) : pill('good', 'All in');
  const cell = s => \`<td class="wu-cell"><a href="\${esc(s.href)}">\${pill(TONE[s.state], s.text)}</a>\${s.sub ? \`<small>\${esc(s.sub)}</small>\` : ''}\${s.canNone && store.can('edit') ? \`<button type="button" class="btn ghost small wu-none" data-wu-none="\${s.feed}|\${s.b}|\${s.we}">None this week</button>\` : ''}</td>\`;
  const hist = Array.from({ length: 8 }, (_, i) => addDays(we, -7 * (i + 1)));
  const mark = s => ({ ok: '✓', late: 'Late', partial: 'Part', missing: '✗', due: '…' })[s.state];
  const histRows = FEEDS.flatMap(f => BLDGS.map(b => \`<tr><td>\${b} · \${esc(f.label)}</td>\${hist.map(w => { const s = weekUploads(w).find(r => r.feed === f.key).cells[b]; return \`<td class="num wu-h \${TONE[s.state]}" title="\${esc(s.text + (s.sub ? ' — ' + s.sub : ''))}">\${mark(s)}</td>\`; }).join('')}</tr>\`)).join('');
  return \`<section class="card cc-card cc-uploads" id="weekly-uploads"><div class="cc-h"><h2>Weekly uploads — week ending \${md(we)}</h2>\${head}</div>
    <p class="muted small">Due every Monday for the week before. Anything missing on Tuesday from 9:00 AM is flagged to the building managers.\${earlier ? \` <b>\${earlier} upload\${earlier === 1 ? '' : 's'} from earlier weeks still missing.</b>\` : ''}</p>
    <div class="table-wrap"><table class="grid cc-table wu-table"><thead><tr><th>Upload</th>\${BLDGS.map(b => \`<th>\${b}</th>\`).join('')}</tr></thead><tbody>
    \${rows.map(r => \`<tr><td><b>\${esc(r.label)}</b>\${r.feed === 'acr' ? '<br><span class="muted small">6049: Electrolit OS&amp;D audits · 6021: WestRock ACRs</span>' : ''}</td>\${BLDGS.map(b => cell(r.cells[b])).join('')}</tr>\`).join('')}
    </tbody></table></div>
    <div class="wu-acts">\${due.length ? \`<button type="button" class="btn primary small" data-wu-email>✉ Email reminder to the managers</button>\` : ''}
      <details class="wu-hist"><summary>Past 8 weeks</summary><div class="table-wrap"><table class="grid cc-table"><thead><tr><th>Upload</th>\${hist.map(w => \`<th class="num">\${md(w)}</th>\`).join('')}</tr></thead><tbody>\${histRows}</tbody></table></div>
      <p class="muted small">✓ uploaded by Monday · Late = after Monday · Part = some trucks missing · ✗ missing. Weeks before \${md(CHECK_FROM)} are shown for reference only.</p></details></div></section>\`;
}

/** Outlook reminder for everything overdue right now. */
export function sendReminder() {
  const items = overdueUploads();
  if (!items.length) return toast('Nothing is late — no reminder needed.');
  const m = reminderEmail(items), none = missingEmails(items);
  openEmail(m);
  toast(none.length ? \`Outlook is opening with the reminder. No email on the Employee Roster for \${none.join(', ')} — add it there (Employees ▸ the manager’s row ▸ Email) and it fills in next time.\` : 'Outlook is opening with the reminder addressed to the managers — check it and press Send.');
}

/** Buttons on the card (None this week, Email reminder). */
export function wireUploads(root) {
  root.addEventListener('click', async e => {
    const none = e.target.closest('[data-wu-none]');
    if (none) {
      const [feed, b, we] = none.dataset.wuNone.split('|');
      none.disabled = true;
      try { await confirmNone(feed, b, we); toast(\`Marked: no \${feed === 'acr' ? 'ACRs' : feed} for \${b}, week ending \${md(we)}\`); }
      catch (err) { none.disabled = false; toast(err.message, 'bad'); }
    }
    if (e.target.closest('[data-wu-email]')) sendReminder();
  });
}

/** Banner (under the top bar) and bell count, for managers and admins. Called on start, data changes and every few minutes. */
export function refreshUploadAlert() {
  const slot = document.querySelector('[data-upload-banner]'), bell = document.querySelector('[data-bell]');
  if (!slot || !bell) return;
  const items = seesAlerts() ? overdueUploads() : [];
  bell.hidden = !items.length;
  bell.querySelector('b').textContent = items.length;
  bell.title = items.length ? \`\${items.length} weekly upload\${items.length === 1 ? '' : 's'} late\` : '';
  if (!items.length) { slot.innerHTML = ''; return; }
  const weeks = [...new Set(items.map(i => i.we))].sort().reverse();
  slot.innerHTML = \`<div class="upl-banner" role="alert"><span class="upl-ic">⚠</span>
    <div><b>\${items.length} weekly upload\${items.length === 1 ? ' is' : 's are'} late</b> for the week ending \${weeks.map(md).join(' and ')} (due Monday): \${esc(items.map(itemText).join(', '))}.</div>
    <a class="btn ghost small" href="#/?focus=uploads">View</a><button type="button" class="btn ghost small" data-upl-email>✉ Email reminder</button></div>\`;
  slot.querySelector('[data-upl-email]').addEventListener('click', sendReminder);
}`]);

